SELECT * FROM operation_log 
WHERE user_id = #{userId} 
ORDER BY create_time DESC

SELECT * FROM operation_log 
WHERE operation_type = #{operationType} 
ORDER BY create_time DESC

SELECT * FROM operation_log 
WHERE user_id = #{userId} 
AND operation_type = #{operationType} 
ORDER BY create_time DESC

SELECT * FROM operation_log 
WHERE create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY create_time DESC
